<template><div class="ui-inline-edit"><template v-if="editing"><UiTextField ref="field" :model-value="draft" density="dense" @update:model-value="draft=$event" @enter="commit"/><UiIconButton icon="check" label="确认" variant="success" density="dense" @click="commit"/><UiIconButton icon="x" label="取消" variant="danger" density="dense" @click="cancel"/></template><template v-else><span :class="{'is-placeholder':!modelValue}">{{modelValue||placeholder}}</span><UiIconButton icon="edit" label="编辑" variant="ghost" density="mini" @click="start"/></template></div></template>
<script setup lang="ts">import{nextTick,ref}from'vue';import UiIconButton from './UiIconButton.vue';import UiTextField from './UiTextField.vue';const props=withDefaults(defineProps<{modelValue:string;placeholder?:string}>(),{placeholder:'未设置'});const emit=defineEmits<{'update:modelValue':[string];save:[string]}>();const editing=ref(false),draft=ref(''),field=ref<InstanceType<typeof UiTextField>>();function start(){draft.value=props.modelValue;editing.value=true;nextTick(()=>field.value?.focus())}function cancel(){editing.value=false}function commit(){emit('update:modelValue',draft.value);emit('save',draft.value);editing.value=false}</script>
<style scoped>.ui-inline-edit{display:flex;min-width:0;align-items:center;gap:4px}.ui-inline-edit>:first-child{min-width:0}.ui-inline-edit>span{overflow:hidden;color:var(--ui-text);font-size:13px;text-overflow:ellipsis;white-space:nowrap}.ui-inline-edit>span.is-placeholder{color:var(--ui-text-soft)}</style>
